00068 const uint32_t kNalHeaderLength = 3;
00069 const uint8_t kNalHeader[kNalHeaderLength] = {0, 0, 1};
00070 const uint32_t kNalEscapeLength = 3;
00071 const uint8_t kNalEscape[kNalEscapeLength] = {0, 0, 3};
00072 const uint8_t kBitCountByteMask[9] = {0, 128, 192, 224, 240, 248, 252, 254, 255};
00073 const uint8_t kMaxNumRefFramesAllowed = 16;
00074 
00075 uint32_t GetBitCountFromMax(uint32_t maxValue) {
00076     // Bit count is determined by ceil(log2(maxRepresentation);
00077     // Because log2 is c99 which is not so widely available we can use standard log with a divide.
00078     // log2(x) = logY(x) / logY(2)
00079     //
00080     // Alternatively we want to find the highest bit set in maxValue.
00081     static const float logBase = log(2.0f);
00082     float log2Value = log(static_cast<float>(maxValue)) / logBase;
00083     return static_cast<uint32_t>(ceil(log2Value));
00084 }
00085 
00086 BaseDecNalUnitType::Enum uFromAVC(uint8_t type) {
00087     switch (type) {
00088     case AVCNalType::Unspecified:
00089     case AVCNalType::CodedSlice_NonIDR:
00090     case AVCNalType::CodedSlice_A:
00091     case AVCNalType::CodedSlice_B:
00092     case AVCNalType::CodedSlice_C:
00093     case AVCNalType::CodedSlice_IDR:
00094     case AVCNalType::CodedSlice_Aux:
00095     case AVCNalType::CodedSlice_Ext:
00096     case AVCNalType::CodedSlice_DepthExt:
00097         return BaseDecNalUnitType::Slice;
00098     case AVCNalType::SEI:
00099         return BaseDecNalUnitType::SEI;
00100     case AVCNalType::SPSExt:
00101     case AVCNalType::SubsetSPS:
00102     case AVCNalType::SPS:
00103         return BaseDecNalUnitType::SPS;
00104     case AVCNalType::PPS:
00105         return BaseDecNalUnitType::PPS;
00106     case AVCNalType::AUD:
00107         return BaseDecNalUnitType::AUD;
00108     case AVCNalType::EndOfSequence:
00109         return BaseDecNalUnitType::EOS;
00110     case AVCNalType::EndOfStream:
00111         return BaseDecNalUnitType::EOB;
00112     case AVCNalType::FillerData:
00113         return BaseDecNalUnitType::Filler;
00114     case AVCNalType::Prefix:
00115     case AVCNalType::DPS:
00116         break;
00117     }
00118 
00119     return BaseDecNalUnitType::Unknown;
00120 }
00121 
00122 uint32_t uOffsetForNalUnitHeader(const uint8_t *nal) {
00123     if (memcmp(nal, kNalHeader, kNalHeaderLength) == 0)
00124         return kNalHeaderLength;
00125     if (!nal[0] && memcmp(nal + 1, kNalHeader, kNalHeaderLength) == 0)
00126         return kNalHeaderLength + 1;
00127     return 0;
00128 }
