00162 bool BaseDecoderAVC::ParseNalUnit(const uint8_t *nal, uint32_t nalLength) {
00163     bool bSuccess = true;
00164 
00165     // Account for AnnexB nal unit header ([0],0,0,1)
00166     uint32_t offset = uOffsetForNalUnitHeader(nal);
00167 
00168     // [forbidden-zero:1, nal_ref_idc:2, nal_type:5]
00169     m_currentNalType = (nal[offset] & 0x1F);
00170     m_currentNalRefIDC = ((nal[offset] >> 5) & 0x3);
00171 
00172     offset += 1;
00173 
00174     BaseDecNalUnitType::Enum nalType = uFromAVC(m_currentNalType);
00175 
00176     if ((nalType == BaseDecNalUnitType::SPS) || (nalType == BaseDecNalUnitType::PPS) || (nalType == BaseDecNalUnitType::SEI) ||
00177         (nalType == BaseDecNalUnitType::Slice)) {
00178         nal += offset;
00179         nalLength -= offset;
00180 
00181         Unencapsulate(nal, nalLength, m_currentNalPayload);
00182         m_currentBits = *m_currentNalPayload.data();
00183         m_remainingBits = 8;
00184         m_byteOffset = 0;
00185 
00186         switch (nalType) {
00187         case BaseDecNalUnitType::PPS:
00188             bSuccess = ParsePPS();
00189             break;
00190         case BaseDecNalUnitType::SPS:
00191             bSuccess = ParseSPS();
00192             break;
00193         case BaseDecNalUnitType::Slice:
00194             if ((bSuccess = ParseSliceHeader())) {
00195                 HandlePictureOrderCount();
00196             }
00197             break;
00198         default:
00199             break;
00200         }
00201     }
00202 
00203     return bSuccess;
00204 }
