00239 uint32_t BaseDecoderAVC::GetPictureWidth() const {
00240     if (!m_activeSPS) {
00241         return 0;
00242     }
00243 
00244     uint32_t cropUnitX = 1; // (7-19)
00245     if (m_activeSPS->m_chromaArrayType != 0 && m_activeSPS->m_chromaArrayType <= 2) {
00246         // subWidthC
00247         cropUnitX = 2; // (7-21)
00248     }
00249 
00250     return m_activeSPS->m_picWidthInMBs * 16 -
00251            cropUnitX * (m_activeSPS->m_frameCropLeftOffset + m_activeSPS->m_frameCropRightOffset); // (D-30)
00252 }
00253 
00254 uint32_t BaseDecoderAVC::GetPictureHeight() const {
00255     if (!m_activeSPS) {
00256         return 0;
00257     }
00258 
00259     uint32_t twoMinusFrameMBsFlag = 2 - m_activeSPS->m_bFrameMBsOnly;
00260     uint32_t cropUnitY = twoMinusFrameMBsFlag; // (7-20)
00261     if (m_activeSPS->m_chromaArrayType != 0) {
00262         // subHeightC * (2 - frame_mbs_only_flag)
00263         cropUnitY = (1 + (m_activeSPS->m_chromaArrayType <= 1)) * (twoMinusFrameMBsFlag); // (7-22)
00264     }
00265 
00266     return twoMinusFrameMBsFlag * m_activeSPS->m_picHeightInMapUnits * 16 -
00267            cropUnitY * (m_activeSPS->m_frameCropTopOffset + m_activeSPS->m_frameCropBottomOffset); // (D-31)
00268 }
