00275 // Section E.2.1 of Standard
00276 uint8_t BaseDecoderAVC::GetMaxNumberOfReorderFrames() const {
00277     if (!m_activeSPS) {
00278         return kMaxNumRefFramesAllowed;
00279     }
00280 
00281     if (m_activeSPS->m_bVUIParametersPresent) {
00282         return m_activeSPS->m_vui.m_maxNumReorderFrames;
00283     }
00284 
00285     if (m_activeSPS->m_bConstraintSet3 &&
00286         (m_activeSPS->m_profileIDC == 44 || m_activeSPS->m_profileIDC == 86 || m_activeSPS->m_profileIDC == 100 ||
00287          m_activeSPS->m_profileIDC == 110 || m_activeSPS->m_profileIDC == 122 || m_activeSPS->m_profileIDC == 244)) {
00288         return 0;
00289     }
00290 
00291     // A.3.1
00292     auto levelLimit = GetLevelLimit(m_activeSPS);
00293     if (!levelLimit) {
00294         return kMaxNumRefFramesAllowed;
00295     }
00296 
00297     uint32_t frameHeightInMbs = (2 - m_activeSPS->m_bFrameMBsOnly) * m_activeSPS->m_picHeightInMapUnits;
00298     uint8_t calculatedMaxNumRefFrames = levelLimit->m_maxDpbMbs / (m_activeSPS->m_picWidthInMBs * frameHeightInMbs);
00299     return std::min(calculatedMaxNumRefFrames, kMaxNumRefFramesAllowed);
00300 }
