00334 // Section 8.2.1 of Standard
00335 void BaseDecoderAVC::HandlePictureOrderCount() {
00336     assert(!m_activeSlice.m_bFieldPic);
00337     assert((m_activeSPS->m_picOrderCntType == 0) || (m_activeSPS->m_picOrderCntType == 2));
00338 
00339     uint32_t topFieldOrderCnt = 0;
00340     uint32_t bottomFieldOrderCnt = 0;
00341 
00342     // 8.2.1.1
00343     if (m_activeSPS->m_picOrderCntType == 0) {
00344         uint32_t prevPicOrderCntMsb = 0;
00345         uint32_t prevPicOrderCntLsb = 0;
00346         uint32_t picOrderCntMsb = 0;
00347         uint32_t maxPicOrderCntLsb = 1 << m_activeSPS->m_log2MaxPicOrderCntLSB;
00348 
00349         if (m_currentNalType == AVCNalType::CodedSlice_IDR) {
00350             prevPicOrderCntMsb = 0;
00351             prevPicOrderCntLsb = 0;
00352         } else if (m_refPic.m_header.m_memManagementControlOp[5]) {
00353             prevPicOrderCntMsb = 0;
00354             prevPicOrderCntLsb = m_refPic.m_header.m_bBottomField ? 0 : m_refPic.m_topFieldOrderCnt;
00355         } else {
00356             prevPicOrderCntMsb = m_refPic.m_picOrderCntMsb;
00357             prevPicOrderCntLsb = m_refPic.m_header.m_picOrderCntLSB;
00358         }
00359 
00360         // (8-3)
00361         if (m_activeSlice.m_picOrderCntLSB < prevPicOrderCntLsb &&
00362             ((prevPicOrderCntLsb - m_activeSlice.m_picOrderCntLSB) >= (maxPicOrderCntLsb / 2))) {
00363             picOrderCntMsb = prevPicOrderCntMsb + maxPicOrderCntLsb;
00364         } else if (m_activeSlice.m_picOrderCntLSB > prevPicOrderCntLsb &&
00365                    ((m_activeSlice.m_picOrderCntLSB - prevPicOrderCntLsb) > (maxPicOrderCntLsb / 2))) {
00366             picOrderCntMsb = prevPicOrderCntMsb - maxPicOrderCntLsb;
00367         } else
00368             picOrderCntMsb = prevPicOrderCntMsb;
00369 
00370         // (8-4), (8-5)
00371         bottomFieldOrderCnt = picOrderCntMsb + m_activeSlice.m_picOrderCntLSB;
00372         topFieldOrderCnt = bottomFieldOrderCnt;
00373 
00374         if (!m_activeSlice.m_bFieldPic)
00375             bottomFieldOrderCnt += m_activeSlice.m_deltaPicOrderCntBottom;
00376 
00377         if (m_currentNalRefIDC != 0) {
00378             m_refPic.m_picOrderCntMsb = picOrderCntMsb;
00379             m_refPic.m_header = m_activeSlice;
00380             m_refPic.m_topFieldOrderCnt = topFieldOrderCnt;
00381             m_refPic.m_bottomFieldOrderCnt = bottomFieldOrderCnt;
00382         }
00383     } else {
00384         uint32_t maxFrameNum = 1 << m_sps->m_log2MaxFrameNum;
00385         uint32_t frameNumOffset = 0;
00386 
00387         // (8-6), (8-11) Calculate frame num offset.
00388         if (m_currentNalType == AVCNalType::CodedSlice_IDR)
00389             frameNumOffset = 0;
00390         else if (m_refPic.m_frameNum > m_activeSlice.m_frameNum)
00391             frameNumOffset = m_refPic.m_frameNumOffset + maxFrameNum;
00392         else
00393             frameNumOffset = m_refPic.m_frameNumOffset;
00394 
00395         if (m_activeSPS->m_picOrderCntType == 1) {
00396             uint32_t absFrameNum = 0;
00397             uint32_t expectedPicOrderCnt = 0;
00398 
00399             // (8-7)
00400             if (m_activeSPS->m_numRefFramesInPicOrderCntCycle != 0)
00401                 absFrameNum = frameNumOffset + m_activeSlice.m_frameNum;
00402             else
00403                 absFrameNum = 0;
00404 
00405             if (m_currentNalRefIDC == 0 && absFrameNum > 0)
00406                 absFrameNum -= 1;
00407 
00408             // (8-9)
00409             if (absFrameNum > 0) {
00410                 // (8-8)
00411                 uint32_t picOrderCntCycleCnt = (absFrameNum - 1) / m_activeSPS->m_numRefFramesInPicOrderCntCycle;
00412                 uint32_t frameNumInPicOrderCntCycle = (absFrameNum - 1) % m_activeSPS->m_numRefFramesInPicOrderCntCycle;
00413 
00414                 // (7-12)
00415                 uint32_t expectedDeltaPerPicOrderCntCycle = 0;
00416                 for (uint32_t i = 0; i < m_activeSPS->m_numRefFramesInPicOrderCntCycle; ++i)
00417                     expectedDeltaPerPicOrderCntCycle += m_activeSPS->m_offsetForRefFrame[i];
00418 
00419                 expectedPicOrderCnt = picOrderCntCycleCnt * expectedDeltaPerPicOrderCntCycle;
00420                 for (uint32_t i = 0; i <= frameNumInPicOrderCntCycle; ++i)
00421                     expectedPicOrderCnt += m_activeSPS->m_offsetForRefFrame[i];
00422             } else
00423                 expectedPicOrderCnt = 0;
00424 
00425             if (m_currentNalRefIDC == 0)
00426                 expectedPicOrderCnt += m_activeSPS->m_offsetForNonRefPic;
00427 
00428             // (8-10)
00429             topFieldOrderCnt = expectedPicOrderCnt + m_activeSlice.m_deltaPicOrderCnt[0];
00430             bottomFieldOrderCnt = topFieldOrderCnt + m_activeSPS->m_offsetForTopToBottomField;
00431 
00432             if (!m_activeSlice.m_bFieldPic)
00433                 bottomFieldOrderCnt += m_activeSlice.m_deltaPicOrderCnt[1];
00434         } else if (m_activeSPS->m_picOrderCntType == 2) {
00435             uint32_t tempPicOrderCnt = 0;
00436             // (8-12) Calculate temp pic order count.
00437             if (m_currentNalType == AVCNalType::CodedSlice_IDR)
00438                 tempPicOrderCnt = 0;
00439             else if (m_currentNalRefIDC == 0)
00440                 tempPicOrderCnt = 2 * (frameNumOffset + m_activeSlice.m_frameNum) - 1;
00441             else
00442                 tempPicOrderCnt = 2 * (frameNumOffset + m_activeSlice.m_frameNum);
00443 
00444             // (8-13)
00445             topFieldOrderCnt = tempPicOrderCnt;
00446             bottomFieldOrderCnt = tempPicOrderCnt;
00447         }
00448 
00449         m_refPic.m_frameNum = m_activeSlice.m_frameNum;
00450         m_refPic.m_frameNumOffset = m_activeSlice.m_memManagementControlOp[5] ? 0 : frameNumOffset;
00451     }
00452 
00453     // (8-1)
00454     if (!m_activeSlice.m_bFieldPic)
00455         m_currentPictureOrderCount = std::min(topFieldOrderCnt, bottomFieldOrderCnt);
00456     else
00457         m_currentPictureOrderCount = m_activeSlice.m_bBottomField ? bottomFieldOrderCnt : topFieldOrderCnt;
00458 }
