00460 bool BaseDecoderAVC::ParseSPS() {
00461     uint8_t profileIDC = ReadBits(8);
00462     bool bConstraintSet0 = ReadFlag();
00463     bool bConstraintSet1 = ReadFlag();
00464     bool bConstraintSet2 = ReadFlag();
00465     bool bConstraintSet3 = ReadFlag();
00466     bool bConstraintSet4 = ReadFlag();
00467     bool bConstraintSet5 = ReadFlag();
00468     uint8_t reservedZero2Bits = ReadBits(2);
00469     uint8_t levelIDC = ReadBits(8);
00470     uint32_t spsID = ReadUE();
00471 
00472     if (spsID >= AVCMaxSPSCount) {
00473         INFO("ERROR -- spsID out of range");
00474         throw std::runtime_error("spsID out of range");
00475         return false;
00476     }
00477 
00478     if (reservedZero2Bits != 0) {
00479         INFO("malformed sps, expected 2 reserved zero bits to be 0");
00480         throw std::runtime_error("malformed sps, expected 2 reserved zero bits to be 0\n");
00481         return false;
00482     }
00483 
00484     m_activeSPS = &m_sps[spsID];
00485     m_activeSPS->m_profileIDC = profileIDC;
00486     m_activeSPS->m_bConstraintSet0 = bConstraintSet0;
00487     m_activeSPS->m_bConstraintSet1 = bConstraintSet1;
00488     m_activeSPS->m_bConstraintSet2 = bConstraintSet2;
00489     m_activeSPS->m_bConstraintSet3 = bConstraintSet3;
00490     m_activeSPS->m_bConstraintSet4 = bConstraintSet4;
00491     m_activeSPS->m_bConstraintSet5 = bConstraintSet5;
00492     m_activeSPS->m_levelIDC = levelIDC;
00493     m_activeSPS->m_spsID = spsID;
00494 
00495     if (m_activeSPS->m_profileIDC == 100 || m_activeSPS->m_profileIDC == 110 || m_activeSPS->m_profileIDC == 122 ||
00496         m_activeSPS->m_profileIDC == 244 || m_activeSPS->m_profileIDC == 44 || m_activeSPS->m_profileIDC == 83 ||
00497         m_activeSPS->m_profileIDC == 86 || m_activeSPS->m_profileIDC == 118 || m_activeSPS->m_profileIDC == 128 ||
00498         m_activeSPS->m_profileIDC == 138 || m_activeSPS->m_profileIDC == 139 || m_activeSPS->m_profileIDC == 134 ||
00499         m_activeSPS->m_profileIDC == 135) {
00500         m_activeSPS->m_chromaFormatIDC = ReadUE();
00501 
00502         if (m_activeSPS->m_chromaFormatIDC == 3) {
00503             m_activeSPS->m_bSeparateColourPlane = ReadFlag();
00504         }
00505 
00506         if (m_activeSPS->m_bSeparateColourPlane == false) {
00507             m_activeSPS->m_chromaArrayType = m_activeSPS->m_chromaFormatIDC;
00508         } else {
00509             m_activeSPS->m_chromaArrayType = 0;
00510         }
00511 
00512         m_activeSPS->m_bitDepthLuma = ReadUE() + 8;
00513         m_activeSPS->m_bitDepthChroma = ReadUE() + 8;
00514         m_activeSPS->m_bQPPrimeYZeroTransformBypass = ReadFlag();
00515 
00516         if (ReadFlag()) // seq_scaling_matrix_present_flag
00517         {
00518             uint32_t loopCount = (m_activeSPS->m_chromaFormatIDC != 3) ? 8 : 12;
00519             HandleScalingList(loopCount);
00520         }
00521     }
00522 
00523     m_activeSPS->m_log2MaxFrameNum = ReadUE() + 4;
00524     m_activeSPS->m_picOrderCntType = ReadUE();
00525 
00526     if (m_activeSPS->m_picOrderCntType == 0) {
00527         m_activeSPS->m_log2MaxPicOrderCntLSB = ReadUE() + 4;
00528     } else if (m_activeSPS->m_picOrderCntType == 1) {
00529         m_activeSPS->m_bDeltaPicOrderAlwaysZero = ReadFlag();
00530         m_activeSPS->m_offsetForNonRefPic = ReadSE();
00531         m_activeSPS->m_offsetForTopToBottomField = ReadSE();
00532         m_activeSPS->m_numRefFramesInPicOrderCntCycle = ReadUE();
00533 
00534         for (uint32_t i = 0; i < m_activeSPS->m_numRefFramesInPicOrderCntCycle; ++i) {
00535             m_activeSPS->m_offsetForRefFrame[i] = ReadSE();
00536         }
00537     }
00538 
00539     m_activeSPS->m_numRefFrames = ReadUE();
00540     m_activeSPS->m_bGapsInFrameNumValueAllowed = ReadFlag();
00541     m_activeSPS->m_picWidthInMBs = ReadUE() + 1;
00542     m_activeSPS->m_picHeightInMapUnits = ReadUE() + 1;
00543     m_activeSPS->m_bFrameMBsOnly = ReadFlag();
00544 
00545     if (m_activeSPS->m_bFrameMBsOnly == false) {
00546         m_activeSPS->m_bMBAdaptiveFrameField = ReadFlag();
00547     }
00548 
00549     m_activeSPS->m_bDirect8x8Inference = ReadFlag();
00550     m_activeSPS->m_bFrameCropping = ReadFlag();
00551 
00552     if (m_activeSPS->m_bFrameCropping) {
00553         m_activeSPS->m_frameCropLeftOffset = ReadUE();
00554         m_activeSPS->m_frameCropRightOffset = ReadUE();
00555         m_activeSPS->m_frameCropTopOffset = ReadUE();
00556         m_activeSPS->m_frameCropBottomOffset = ReadUE();
00557     }
00558 
00559     m_activeSPS->m_bVUIParametersPresent = ReadFlag();
00560 #if !defined(NO_VUIPARAMS)
00561     if (m_activeSPS->m_bVUIParametersPresent)
00562         HandleVUIParameters();
00563 #endif
00564     return true;
00565 }
