00567 bool BaseDecoderAVC::ParsePPS() {
00568     uint32_t ppsID = ReadUE();
00569 
00570     if (ppsID >= AVCMaxPPSCount) {
00571         INFO("ppsID out of range");
00572         throw std::runtime_error("ppsID out of range");
00573         return false;
00574     }
00575 
00576     m_activePPS = &m_pps[ppsID];
00577     m_activePPS->m_ppsID = ppsID;
00578     m_activePPS->m_spsID = ReadUE();
00579     m_activePPS->m_bEntropyCodingMode = ReadFlag();
00580     m_activePPS->m_bBottomFieldPicOrderInFramePresent = ReadFlag();
00581     m_activePPS->m_numSliceGroups = ReadUE() + 1;
00582 
00583     if (m_activePPS->m_numSliceGroups > 1) {
00584         m_activePPS->m_sliceGroupMapType = ReadUE();
00585 
00586         switch (m_activePPS->m_sliceGroupMapType) {
00587         case 0: {
00588             for (uint32_t group = 0; group < m_activePPS->m_numSliceGroups; ++group) {
00589                 m_activePPS->m_runLength[group] = ReadUE() + 1;
00590             }
00591             break;
00592         }
00593         case 2: {
00594             for (uint32_t group = 0; group < m_activePPS->m_numSliceGroups; ++group) {
00595                 m_activePPS->m_topLeft[group] = ReadUE();
00596                 m_activePPS->m_bottomRight[group] = ReadUE();
00597             }
00598             break;
00599         }
00600         case 3:
00601         case 4:
00602         case 5: {
00603             m_activePPS->m_bSliceGroupChangeDirection = ReadFlag();
00604             m_activePPS->m_sliceGroupChangeRate = ReadUE() + 1;
00605             break;
00606         }
00607         case 6: {
00608             INFO("Unsupported slice group map type");
00609             throw std::runtime_error("Unsupported slice group map type");
00610             break;
00611         }
00612         default:
00613             break;
00614         }
00615     }
00616 
00617     m_activePPS->m_numRefIDXL0Active = ReadUE() + 1;
00618     m_activePPS->m_numRefIDXL1Active = ReadUE() + 1;
00619     m_activePPS->m_bWeightedPred = ReadFlag();
00620     m_activePPS->m_weightedBipredIDC = ReadBits(2);
00621     m_activePPS->m_picInitQP = ReadSE() + 26;
00622     m_activePPS->m_picInitQS = ReadSE() + 26;
00623     m_activePPS->m_chromaQPIndexOffset = ReadSE();
00624     m_activePPS->m_bDeblockingFilterControlPresent = ReadFlag();
00625     m_activePPS->m_bConstraintedIntraPred = ReadFlag();
00626     m_activePPS->m_bRedundantPicCntPresent = ReadFlag();
00627 
00628     return true;
00629 }
