00631 bool BaseDecoderAVC::ParseSliceHeader() {
00632     m_activeSlice.m_firstMBInSlice = ReadUE();
00633 
00634     uint32_t sliceType = ReadUE();
00635     if (sliceType > 4)
00636         sliceType -= 5;
00637 
00638     m_activeSlice.m_sliceType = static_cast<SliceType::Enum>(sliceType);
00639     m_activeSlice.m_ppsID = ReadUE();
00640     m_activeSlice.m_pps = &m_pps[m_activeSlice.m_ppsID];
00641     m_activeSlice.m_sps = &m_sps[m_activeSlice.m_pps->m_spsID];
00642 
00643     if (m_activeSlice.m_sps->m_bSeparateColourPlane) {
00644         m_activeSlice.m_colourPlaneID = ReadBits(2);
00645     }
00646 
00647     m_activeSlice.m_frameNum = ReadBits(m_activeSlice.m_sps->m_log2MaxFrameNum);
00648 
00649     if (m_activeSlice.m_sps->m_bFrameMBsOnly == false) {
00650         m_activeSlice.m_bFieldPic = ReadFlag();
00651 
00652         if (m_activeSlice.m_bFieldPic) {
00653             m_activeSlice.m_bBottomField = ReadFlag();
00654         }
00655     }
00656 
00657     if (m_currentNalType == 5) // if(IdrPicFlag)
00658     {
00659         m_activeSlice.m_idrPicID = ReadUE();
00660         m_activeSlice.m_bIDR = true;
00661     } else {
00662         m_activeSlice.m_bIDR = false;
00663     }
00664 
00665     if (m_activeSlice.m_sps->m_picOrderCntType == 0) {
00666         m_activeSlice.m_picOrderCntLSB = ReadBits(m_activeSlice.m_sps->m_log2MaxPicOrderCntLSB);
00667 
00668         if (m_activeSlice.m_pps->m_bBottomFieldPicOrderInFramePresent && (m_activeSlice.m_bFieldPic == false)) {
00669             m_activeSlice.m_deltaPicOrderCntBottom = ReadSE();
00670         }
00671     }
00672 
00673     if (m_activeSlice.m_sps->m_picOrderCntType == 1 && (m_activeSlice.m_sps->m_bDeltaPicOrderAlwaysZero == false)) {
00674         m_activeSlice.m_deltaPicOrderCnt[0] = ReadSE();
00675 
00676         if (m_activeSlice.m_pps->m_bBottomFieldPicOrderInFramePresent && (m_activeSlice.m_bFieldPic == false)) {
00677             m_activeSlice.m_deltaPicOrderCnt[1] = ReadSE();
00678         }
00679     }
00680 
00681     if (m_activeSlice.m_pps->m_bRedundantPicCntPresent) {
00682         m_activeSlice.m_redundantPicCnt = ReadUE();
00683     }
00684 
00685     if (m_activeSlice.m_sliceType == SliceType::B) {
00686         m_activeSlice.m_bDirectSpatialMVPred = ReadFlag();
00687     }
00688 
00689     m_activeSlice.m_numRefIDXL0Active = m_activeSlice.m_pps->m_numRefIDXL0Active;
00690     m_activeSlice.m_numRefIDXL1Active = m_activeSlice.m_pps->m_numRefIDXL1Active;
00691 
00692     if ((m_activeSlice.m_sliceType == SliceType::P) || (m_activeSlice.m_sliceType == SliceType::SP) ||
00693         (m_activeSlice.m_sliceType == SliceType::B)) {
00694         m_activeSlice.m_bNumRefIDXActiveOverrideFlag = ReadFlag();
00695 
00696         if (m_activeSlice.m_bNumRefIDXActiveOverrideFlag) {
00697             m_activeSlice.m_numRefIDXL0Active = ReadUE() + 1;
00698 
00699             if (m_activeSlice.m_sliceType == SliceType::B) {
00700                 m_activeSlice.m_numRefIDXL1Active = ReadUE() + 1;
00701             }
00702         }
00703     }
00704 
00705     HandleRefPicListReordering();
00706 
00707     if ((m_activeSlice.m_pps->m_bWeightedPred &&
00708          (m_activeSlice.m_sliceType == SliceType::P || m_activeSlice.m_sliceType == SliceType::SP)) ||
00709         (m_activeSlice.m_pps->m_weightedBipredIDC == 1 && m_activeSlice.m_sliceType == SliceType::B)) {
00710         HandlePredWeightTable();
00711     }
00712 
00713     if (m_currentNalRefIDC != 0) {
00714         HandleDecRefPicMarking();
00715     }
00716 
00717     if (m_activeSlice.m_pps->m_bEntropyCodingMode && (m_activeSlice.m_sliceType != SliceType::I) &&
00718         (m_activeSlice.m_sliceType != SliceType::SI)) {
00719         m_activeSlice.m_cabacInitIDC = ReadUE();
00720     } else {
00721         m_activeSlice.m_cabacInitIDC = 0;
00722     }
00723 
00724     m_activeSlice.m_sliceQPDelta = ReadSE();
00725     // m_activeSlice.m_pps->m_picInitQP += m_activeSlice.m_sliceQPDelta;
00726 
00727     if ((m_activeSlice.m_sliceType == SliceType::SP) || (m_activeSlice.m_sliceType == SliceType::SI)) {
00728         if (m_activeSlice.m_sliceType == SliceType::SP) {
00729             m_activeSlice.m_bSPForSwitch = ReadFlag();
00730         }
00731 
00732         m_activeSlice.m_sliceQSDelta = ReadSE();
00733     }
00734 
00735     m_activeSlice.m_disableDeblockingFilterIDC = 0;
00736     m_activeSlice.m_sliceAlphaC0OffsetDiv2 = 0;
00737     m_activeSlice.m_sliceBetaOffsetDiv2 = 0;
00738 
00739     if (m_activeSlice.m_pps->m_bDeblockingFilterControlPresent) {
00740         m_activeSlice.m_disableDeblockingFilterIDC = ReadUE();
00741 
00742         if (m_activeSlice.m_disableDeblockingFilterIDC != 1) {
00743             m_activeSlice.m_sliceAlphaC0OffsetDiv2 = ReadSE();
00744             m_activeSlice.m_sliceBetaOffsetDiv2 = ReadSE();
00745         }
00746     }
00747 
00748     return true;
00749 }
