00751 void BaseDecoderAVC::HandleVUIParameters() {
00752     if (ReadFlag()) // aspect_ratio_info_present_flag
00753     {
00754         if (ReadBits(8) == 255) // aspect_ratio_idc == Extended_SAR
00755         {
00756             ReadBits(16); // sar_width
00757             ReadBits(16); // sar_height
00758         }
00759     }
00760 
00761     if (ReadFlag()) // overscan_info_present_flag
00762     {
00763         ReadFlag(); // overscan_appropriate_flag
00764     }
00765 
00766     if (ReadFlag()) // video_signal_type_present_flag
00767     {
00768         ReadBits(3);    // video_format
00769         ReadFlag();     // video_full_range_flag
00770         if (ReadFlag()) // colour_description_present_flag
00771         {
00772             ReadBits(8); // colour_primaries
00773             ReadBits(8); // transfer_characteristics
00774             ReadBits(8); // matrix_coefficients
00775         }
00776     }
00777     if (ReadFlag()) // chroma_loc_info_present_flag
00778     {
00779         ReadUE(); // chroma_sample_loc_type_top_field
00780         ReadUE(); // chroma_sample_loc_type_bottom_field
00781     }
00782     if ((m_activeSPS->m_vui.m_bTimingInfoPresent = ReadFlag())) {
00783         m_activeSPS->m_vui.m_numUnitsInTick = ReadBits(32);
00784         m_activeSPS->m_vui.m_timeScale = ReadBits(32);
00785         ReadFlag(); // fixed_frame_rate_flag
00786     }
00787     bool nalHRDParametersPresentFlag = ReadFlag();
00788     if (nalHRDParametersPresentFlag) {
00789         HandleHRDParameters();
00790     }
00791     bool vclHRDParametersPresentFlag = ReadFlag();
00792     if (vclHRDParametersPresentFlag) {
00793         HandleHRDParameters();
00794     }
00795     if (nalHRDParametersPresentFlag || vclHRDParametersPresentFlag) {
00796         ReadFlag(); // low_delay_hrd_flag
00797     }
00798     ReadFlag();     // pic_struct_present_flag
00799     if (ReadFlag()) // bitstream_restriction_flag
00800     {
00801         ReadFlag(); // motion_vectors_over_pic_boundaries_flag
00802         ReadUE();   // max_bytes_per_pic_denom
00803         ReadUE();   // max_bits_per_mb_denom
00804         ReadUE();   // log2_max_mv_length_horizontal
00805         ReadUE();   // log2_max_mv_length_vertical
00806         m_activeSPS->m_vui.m_maxNumReorderFrames = ReadUE();
00807         ReadUE(); // max_dec_frame_buffering
00808     }
00809 }
00810 
00811 void BaseDecoderAVC::HandleHRDParameters() {
00812     uint32_t cpbCnt = ReadUE() + 1;
00813     ReadBits(4); // bit_rate_scale
00814     ReadBits(4); // cpb_size_scale
00815 
00816     for (uint32_t i = 0; i < cpbCnt; i++) {
00817         ReadUE();   // bit_rate_value_minus1[i]
00818         ReadUE();   // cpb_size_value_minus1[i]
00819         ReadFlag(); // cbr_flag[i]
00820     }
00821     ReadBits(5); // initial_cpb_removal_delay_length_minus1
00822     ReadBits(5); // cpb_removal_delay_length_minus1
00823     ReadBits(5); // dpb_output_delay_length_minus1
00824     ReadBits(5); // time_offset_length
00825 }
00826 
00827 bool BaseDecoderAVC::HandleRefPicListReordering() {
00828     if (m_activeSlice.m_sliceType != SliceType::I && m_activeSlice.m_sliceType != SliceType::SI) {
00829         bool bRefPicListReorderingFlagL0 = ReadFlag();
00830 
00831         if (bRefPicListReorderingFlagL0) {
00832             uint32_t reorderingOfPicNumsIDC;
00833 
00834             do {
00835                 reorderingOfPicNumsIDC = ReadUE();
00836 
00837                 if ((reorderingOfPicNumsIDC == 0) || (reorderingOfPicNumsIDC == 1)) {
00838                     ReadUE(); // abs_diff_pic_num_minus1
00839                 } else if (reorderingOfPicNumsIDC == 2) {
00840                     ReadUE(); // long_term_pic_num
00841                 }
00842 
00843             } while (reorderingOfPicNumsIDC != 3);
00844         }
00845     }
00846 
00847     if (m_activeSlice.m_sliceType == SliceType::B) {
00848         bool bRefPicListReorderingFlagL1 = ReadFlag();
00849 
00850         if (bRefPicListReorderingFlagL1) {
00851             uint32_t reorderingOfPicNumsIDC;
00852 
00853             do {
00854                 reorderingOfPicNumsIDC = ReadUE();
00855 
00856                 if ((reorderingOfPicNumsIDC == 0) || (reorderingOfPicNumsIDC == 1)) {
00857                     ReadUE(); // abs_diff_pic_num_minus1
00858                 } else if (reorderingOfPicNumsIDC == 2) {
00859                     ReadUE(); // long_term_pic_num
00860                 }
00861 
00862             } while (reorderingOfPicNumsIDC != 3);
00863         }
00864     }
00865 
00866     return true;
00867 }
00868 
00869 bool BaseDecoderAVC::HandlePredWeightTable() {
00870     ReadUE(); // luma_log2_weight_dneom
00871 
00872     if (m_activeSlice.m_sps->m_chromaArrayType != 0) {
00873         ReadUE(); // chroma_log2_weight_denom
00874     }
00875 
00876     for (uint32_t i = 0; i < m_activeSlice.m_numRefIDXL0Active; ++i) {
00877         if (ReadFlag()) // luma_weight_l0_flag
00878         {
00879             ReadSE(); // luma_weight_l0[i]
00880             ReadSE(); // luma_offset_l0[i]
00881         }
00882 
00883         if (m_activeSlice.m_sps->m_chromaArrayType != 0) {
00884             if (ReadFlag()) // chroma_weight_l0_flag
00885             {
00886                 for (uint32_t j = 0; j < 2; ++j) {
00887                     ReadSE(); // chroma_weight_l0[i][j]
00888                     ReadSE(); // chroma_offset_l0[i][j]
00889                 }
00890             }
00891         }
00892     }
00893 
00894     if (m_activeSlice.m_sliceType == SliceType::B) {
00895         for (uint32_t i = 0; i < m_activeSlice.m_numRefIDXL1Active; ++i) {
00896             if (ReadFlag()) // luma_weight_l1_flag
00897             {
00898                 ReadSE(); // luma_weight_l1[i]
00899                 ReadSE(); // luma_offset_l1[i]
00900             }
00901 
00902             if (m_activeSlice.m_sps->m_chromaArrayType != 0) {
00903                 if (ReadFlag()) // chroma_weight_l1_flag
00904                 {
00905                     for (uint32_t j = 0; j < 2; ++j) {
00906                         ReadSE(); // chroma_weight_l1[i][j]
00907                         ReadSE(); // chroma_offset_l1[i][j]
00908                     }
00909                 }
00910             }
00911         }
00912     }
00913 
00914     return true;
00915 }
00916 
00917 bool BaseDecoderAVC::HandleDecRefPicMarking() {
00918     if (m_currentNalType == 5) {
00919         ReadFlag(); // no_output_of_prior_pics_flag
00920         ReadFlag(); // long_term_reference_flag
00921     } else {
00922         if (ReadFlag()) // adaptive_ref_pic_marking_mode_flag
00923         {
00924             uint32_t memManagementControlOp;
00925 
00926             do {
00927                 memManagementControlOp = ReadUE();
00928 
00929                 if (memManagementControlOp < AVCNumMMCO)
00930                     m_activeSlice.m_memManagementControlOp[memManagementControlOp] = true;
00931 
00932                 if ((memManagementControlOp == 1) || (memManagementControlOp == 3)) {
00933                     ReadUE(); // difference_of_pic_nums_minus1
00934                 }
00935                 if (memManagementControlOp == 2) {
00936                     ReadUE(); // long_term_pic_num
00937                 }
00938 
00939                 if ((memManagementControlOp == 3) || (memManagementControlOp == 6)) {
00940                     ReadUE(); // long_term_frame_idx
00941                 }
00942 
00943                 if (memManagementControlOp == 4) {
00944                     ReadUE(); // max_long_term_Frame_idx_plus1
00945                 }
00946 
00947             } while (memManagementControlOp != 0);
00948         }
00949     }
00950 
00951     return true;
00952 }
00953 
00954 bool BaseDecoderAVC::HandleScalingList(uint32_t loopCount) {
00955     for (uint32_t i = 0; i < loopCount; ++i) {
00956         if (ReadFlag()) // seq_scaling_list_present_flag
00957         {
00958             if (i < 6) {
00959                 HandleScalingListElement(16);
00960             } else {
00961                 HandleScalingListElement(64);
00962             }
00963         }
00964     }
00965 
00966     return true;
00967 }
00968 
00969 bool BaseDecoderAVC::HandleScalingListElement(uint32_t listSize) {
00970     int32_t lastScale = 8;
00971     int32_t nextScale = 8;
00972     int32_t deltaScale;
00973 
00974     for (uint32_t j = 0; j < listSize; ++j) {
00975         if (nextScale != 0) {
00976             deltaScale = ReadSE();
00977             nextScale = (lastScale + deltaScale + 256) % 256;
00978         }
00979         lastScale = (nextScale == 0) ? lastScale : nextScale;
00980     }
00981 
00982     return true;
00983 }
