00985 // A.3.1
00986 const BaseDecoderAVC::Level::Limit *BaseDecoderAVC::GetLevelLimit(SPS *sps) const {
00987     if (!sps) {
00988         return nullptr;
00989     }
00990 
00991     Level::Enum level = static_cast<Level::Enum>(sps->m_levelIDC);
00992     if (level == Level::Number_1_1 && sps->m_bConstraintSet3) {
00993         level = Level::Number_1b;
00994     }
00995     auto limits = Level::limits;
00996     return limits.find(level) != limits.end() ? &Level::limits.at(level) : nullptr;
00997 }
